// MCP tools for batch 76 (3-Nov-2026): printable paper airplane fold sheets and paper crown templates.
// The pure cores come from src/tools_core76.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/
// printpdf-core-72d.js, tpl-core-76a.js, plane-core-76a.js, crown-core-76a.js) — one source of truth with the /tools/ pages
// paper-airplane-template and paper-crown-template. Stateless: no D1/R2, no fetch. Both are deterministic.
import { MGD76 } from "./tools_core76.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => ({ content: [{ type: "text", text }], structuredContent });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const fence = (lang, s) => "```" + lang + "\n" + String(s).replace(/\n$/, "") + "\n```";
const OUT_CAP = 120 * 1024;
const num = (v) => (v === undefined || v === null || v === "" ? undefined : Number(v));
const fin = (v) => Number.isFinite(num(v));
const int = (v, a, b) => Number.isInteger(num(v)) && num(v) >= a && num(v) <= b;
const PL = MGD76.plane, CR = MGD76.crown, TP = MGD76.tpl;
const DESIGNS = PL.DESIGNS.map((d) => d[0]), PSHEETS = Object.keys(PL.SHEETS);
const STYLES = CR.STYLES.map((s) => s[0]), PRESETS = CR.PRESETS.map((p) => p[0]), CPAPERS = ["letter", "a4", "a3", "tabloid"];
const FILLS = TP.FILLS.map((f) => f[0]).filter((f) => f !== "image");
const UNITS = { mm: 1, cm: 10, in: 25.4 };
const HEX = /^#[0-9a-f]{6}$/i;
const r1 = (v) => Math.round(v * 10) / 10;
const fmtLen = (mm, u) => (u === "mm" ? Math.round(mm) + " mm" : r1(mm / UNITS[u]) + (u === "in" ? " in" : " cm"));
// the SVG art options shared by both tools (pattern fill under the cut / fold lines)
function artOpts(a, defFill, title) {
  if (a.fill !== undefined && !FILLS.includes(a.fill)) return { e: "fill must be one of: " + FILLS.join(", ") + "." };
  if (a.color !== undefined && !HEX.test(String(a.color))) return { e: "color must be a #rrggbb hex colour." };
  const c1 = a.color !== undefined ? String(a.color) : "#ffd23f";
  return { o: { fill: a.fill || defFill, color: c1, color2: "#ffffff", palette: [c1, "#ee4266", "#3bceac", "#540d6e"], seed: 7, title } };
}

export const TOOL_DEFS = [
  {
    name: "make_paper_airplane_template",
    description: "Use when a kids' activity, classroom STEM lesson or party needs a printable paper airplane: classic dart, glider or Nakamura lock on US Letter or A4, with every crease worked out by a folding simulator and marked valley (towards you) or mountain (away), numbered by step, plus the step-by-step folding text. Returns the true-size SVG sheet and the crease segments in mm.",
    inputSchema: {
      type: "object",
      properties: {
        design: { type: "string", enum: DESIGNS, description: "Default dart." },
        paper: { type: "string", enum: PSHEETS, description: "Default letter." },
        numbers: { type: "boolean", description: "Step numbers on the lines (default true)." },
        text: { type: "string", description: "Name or word printed on both wings." },
        fill: { type: "string", enum: FILLS, description: "Default none (white)." },
        color: { type: "string", description: "#rrggbb." },
      },
    },
    annotations: RO("Paper airplane template"),
  },
  {
    name: "make_crown_template",
    description: "Use when a birthday, school play or party needs a printable paper crown that fits: band = head circumference + overlap, points spaced evenly (classic, jewelled, rounded, castle or tiara), split into numbered pieces with glue tabs when it is longer than the paper. Returns the band length, pieces, sheet count and true-size SVG sheets.",
    inputSchema: {
      type: "object",
      properties: {
        head_circumference: { type: "number", description: "Default 57 cm." },
        unit: { type: "string", enum: Object.keys(UNITS), description: "All lengths (default cm)." },
        preset: { type: "string", enum: PRESETS },
        style: { type: "string", enum: STYLES },
        points: { type: "integer", description: "2-40." },
        overlap: { type: "number", description: "Default 2.5 cm." },
        band: { type: "number", description: "Depth (default 3 cm)." },
        height: { type: "number", description: "Of the points (default 6 cm)." },
        paper: { type: "string", enum: CPAPERS },
        text: { type: "string", description: "Name on the front." },
        gems: { type: "boolean", description: "Default true." },
        fill: { type: "string", enum: FILLS, description: "Default solid." },
        color: { type: "string", description: "#rrggbb (default gold)." },
      },
    },
    annotations: RO("Paper crown template"),
  },
];

export const NEXT76 = {
  make_paper_airplane_template: "Next step: open the paper airplane link to add a pattern or picture and print the true-size PDF with the folding instructions page.",
  make_crown_template: "Next step: open the paper crown link to add a photo or pattern and print the pieces as a true-size PDF on card stock.",
};

// ---- paper airplane
function airplane(a) {
  if (a.design !== undefined && !DESIGNS.includes(a.design)) return err("design must be one of: " + DESIGNS.join(", ") + ".");
  if (a.paper !== undefined && !PSHEETS.includes(a.paper)) return err("paper must be one of: " + PSHEETS.join(", ") + ".");
  const text = a.text !== undefined ? str(a.text, 24) : "";
  const r = PL.plane({ design: a.design || "dart", paper: a.paper || "letter", numbers: a.numbers !== false, text });
  const name = PL.DESIGNS.filter((d) => d[0] === r.design)[0][1], page = `${T}/paper-airplane-template/`;
  const ao = artOpts(a, "none", "Paper airplane: " + name + " (" + r.paper + ")");
  if (ao.e) return err(ao.e);
  const svg = TP.svg(r.page, ao.o);
  const valley = r.creases.filter((c) => c.type === "valley").length, mountain = r.creases.length - valley;
  const lines = [`**Paper airplane: ${name} on ${r.paper} (${r.W} × ${r.H} mm, nose at the top): ${r.steps.length} steps, ${r.creases.length} crease segments (${valley} valley = fold towards you, ${mountain} mountain = fold away).**`,
    "Folding steps (line numbers match the sheet):", ...r.steps.map((s, i) => `${i + 1}. ${s}`)];
  const sc = { design: r.design, name, paper: a.paper || "letter", sheet_mm: [r.W, r.H], steps: r.steps, valley, mountain,
    creases: r.creases.map((c) => ({ step: c.step, type: c.type, a: c.a, b: c.b })), page };
  if (svg.length <= OUT_CAP) { lines.push(`True-size SVG (${Math.round(svg.length / 1024)} KB; print at 100%, edge to edge; valley = pink dash-dot, mountain = blue dashes):`, fence("svg", svg)); sc.svg = svg; }
  else { lines.push("The SVG is too large to return inline: open the page to download it."); sc.svg_too_large = true; }
  lines.push("Patterns, your picture and a print-ready PDF with the instructions: " + page);
  return ok(lines.join("\n"), sc);
}

// ---- paper crown
function crown(a) {
  if (a.unit !== undefined && !UNITS[a.unit]) return err("unit must be one of: " + Object.keys(UNITS).join(", ") + ".");
  if (a.preset !== undefined && !PRESETS.includes(a.preset)) return err("preset must be one of: " + PRESETS.join(", ") + ".");
  if (a.style !== undefined && !STYLES.includes(a.style)) return err("style must be one of: " + STYLES.join(", ") + ".");
  if (a.paper !== undefined && !CPAPERS.includes(a.paper)) return err("paper must be one of: " + CPAPERS.join(", ") + ".");
  if (a.points !== undefined && !int(a.points, 2, 40)) return err("points must be an integer 2-40.");
  for (const k of ["head_circumference", "overlap", "band", "height"]) if (a[k] !== undefined && !(fin(a[k]) && num(a[k]) >= 0)) return err(k + " must be a positive number.");
  const u = a.unit || "cm", k = UNITS[u], mm = (v) => (v === undefined ? undefined : num(v) * k);
  const head = a.head_circumference !== undefined ? mm(a.head_circumference) : a.preset ? CR.PRESETS.filter((p) => p[0] === a.preset)[0][2] : 570;
  if (!(head >= 200 && head <= 800)) return err(`head_circumference must be 20-80 cm (8-31 in); got ${fmtLen(head, u)}.`);
  const ov = mm(a.overlap), b = mm(a.band), h = mm(a.height);
  if (ov !== undefined && !(ov >= 10 && ov <= 60)) return err("overlap must be 1-6 cm (10-60 mm).");
  if (b !== undefined && !(b >= 12 && b <= 80)) return err("band must be 1.2-8 cm (12-80 mm).");
  if (h !== undefined && h > 200) return err("height must be at most 20 cm (200 mm).");
  const text = a.text !== undefined ? str(a.text, 40) : "";
  const r = CR.crown({ head, overlap: ov, band: b, height: h, points: a.points === undefined ? undefined : num(a.points), style: a.style, paper: a.paper || "letter", gems: a.gems !== false, text });
  if (!r.ok) return err(r.error);
  const sname = CR.STYLES.filter((s) => s[0] === r.style)[0][1].replace(/ \(.*\)$/, ""), np = r.pieces.length, page = `${T}/paper-crown-template/`;
  const ao = artOpts(a, "solid", "Paper crown: head " + fmtLen(r.head, u));
  if (ao.e) return err(ao.e);
  const svgs = r.pages.map((pg, i) => TP.svg(pg, Object.assign({}, ao.o, { idSuffix: "s" + i })));
  const total = svgs.reduce((s, x) => s + x.length, 0);
  const pieces = r.pieces.map((pc, i) => ({ piece: i + 1, from_mm: pc.xa, to_mm: pc.xb, width_mm: pc.w, glue_tab_mm: pc.tab }));
  const lines = [`**Paper crown (${sname}): band ${fmtLen(r.L, u)} long = head ${fmtLen(r.head, u)} + ${fmtLen(r.overlap, u)} overlap; ${r.n} points every ${fmtLen(r.period, u)}, ${fmtLen(r.band + r.height, u)} tall (band ${fmtLen(r.band, u)} + points ${fmtLen(r.height, u)}); ${np} piece${np > 1 ? "s" : ""} on ${r.pages.length} landscape ${(a.paper || "letter").toUpperCase()} sheet${r.pages.length > 1 ? "s" : ""}.**`,
    ...(np > 1 ? ["Pieces (each but the last has a 15 mm GLUE UNDER tab): " + pieces.map((p) => `${p.piece}: ${fmtLen(p.width_mm, u)}`).join(", ") + "."] : []),
    ...r.warnings.map((w) => "Note: " + w),
    "Print at 100% on card stock, cut the outlines, join the pieces in number order, then glue or staple the OVERLAP at the back."];
  const sc = { style: r.style, unit: u, head_mm: r.head, overlap_mm: r.overlap, band_length_mm: r.L, band_mm: r.band, point_height_mm: r.height, points: r.n, point_spacing_mm: r.period,
    paper: a.paper || "letter", sheets: r.pages.length, pieces, warnings: r.warnings, page };
  if (total <= OUT_CAP) { svgs.forEach((s, i) => lines.push(`Sheet ${i + 1} of ${svgs.length} (true size, ${Math.round(s.length / 1024)} KB):`, fence("svg", s))); sc.svgs = svgs; }
  else { lines.push("The SVG sheets are too large to return inline: open the page to download them."); sc.svg_too_large = true; }
  lines.push("Photo or pattern fills and a print-ready PDF: " + page);
  return ok(lines.join("\n"), sc);
}

const HANDLERS = { make_paper_airplane_template: airplane, make_crown_template: crown };
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools76Tool(name) { return NAMES.has(name); }
export async function callTools76Tool(name, a) {
  a = a && typeof a === "object" ? a : {};
  try {
    if (HANDLERS[name]) return HANDLERS[name](a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}
